WITH flagged AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at, id) + INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_session FROM sessions), islands AS (SELECT id, customer_id, browser, started_at, country, SUM(is_new_session) OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT s.id, s.customer_id, s.browser, s.started_at, s.country, CASE WHEN country RLIKE '^(JP|UK)$' THEN 'GROUP_B' WHEN country RLIKE '^(TH|US)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS country_zone, (SELECT SUM(x.monthly_fee) FROM subscriptions x WHERE x.customer_id = s.customer_id) AS sum_subscription_monthly_fee FROM islands s;
